import { encodeNumbersSequence } from 'xneek-gpx';

export const sequenceJoinSymbol = '\n';

export const getTrackDataFromCoordinates = (
  coordinates: Array<[number, number, number] | [number, number]>,
): string => {
  const lats = encodeNumbersSequence(coordinates.map((x) => x[0]));
  const lons = encodeNumbersSequence(coordinates.map((x) => x[1]));
  let eles = null;
  if (coordinates.some((c) => !!c[2])) {
    eles = encodeNumbersSequence(coordinates.map((x) => x[2] || 0));
  }
  const trackData = [lats, lons, eles].filter(Boolean).join(sequenceJoinSymbol);

  return trackData;
};
